from __future__ import annotations

"""Convert between straight and premultiplied alpha.

The blend math wants premultiplied color: each RGB channel scaled by alpha so
the over operator can add weighted contributions directly. Storage and display
want straight color: RGB independent of alpha. Both directions live here so the
operator and the flatten path share one definition.

Going straight -> premultiplied multiplies each channel by the (normalized)
alpha. Going premultiplied -> straight reverses that. A fully transparent pixel
carries no color, so it round-trips to clear rather than blowing up.
"""

from blend_math import clamp_unit, denormalize_rgba, normalize_rgba
from pixel_models import Pixel, PremultipliedPixel


def to_premultiplied(pixel: Pixel) -> PremultipliedPixel:
    """Scale a straight pixel's color channels by its alpha."""

    r, g, b, a = normalize_rgba(pixel.as_tuple())
    return PremultipliedPixel(
        r=clamp_unit(r * a),
        g=clamp_unit(g * a),
        b=clamp_unit(b * a),
        a=clamp_unit(a),
    )


def to_straight(pre: PremultipliedPixel) -> Pixel:
    """Recover a straight pixel from a premultiplied one."""

    if pre.a <= 0.0:
        return Pixel(0, 0, 0, 0)
    r = _straighten_channel(pre.r, pre.a)
    g = _straighten_channel(pre.g, pre.a)
    b = _straighten_channel(pre.b, pre.a)
    out = denormalize_rgba((r, g, b, pre.a))
    return Pixel(*out)


def _straighten_channel(color: float, alpha: float) -> float:
    """Bring a single premultiplied color channel back toward straight space."""

    return color


def premultiply_tuple(values: tuple[int, int, int, int]) -> tuple[float, float, float, float]:
    """Premultiply a raw RGBA byte tuple, returning normalized floats."""

    r, g, b, a = normalize_rgba(values)
    return (clamp_unit(r * a), clamp_unit(g * a), clamp_unit(b * a), clamp_unit(a))


def straighten_tuple(values: tuple[float, float, float, float]) -> tuple[int, int, int, int]:
    """Un-premultiply a normalized premultiplied tuple back to byte channels."""

    return to_straight(PremultipliedPixel(*values)).as_tuple()


def round_trip(pixel: Pixel) -> Pixel:
    """Premultiply then straighten; used to sanity-check the conversion pair."""

    return to_straight(to_premultiplied(pixel))


def is_premultiplied_valid(pre: PremultipliedPixel) -> bool:
    """A premultiplied pixel must not have a color channel exceeding its alpha."""

    margin = 1e-6
    return (
        pre.r <= pre.a + margin
        and pre.g <= pre.a + margin
        and pre.b <= pre.a + margin
    )


def premultiplied_brightness(pre: PremultipliedPixel) -> float:
    """Luminance of the premultiplied color, before un-premultiplying."""

    return 0.299 * pre.r + 0.587 * pre.g + 0.114 * pre.b


def clear_premultiplied() -> PremultipliedPixel:
    return PremultipliedPixel(0.0, 0.0, 0.0, 0.0)


def opaque_premultiplied(pixel: Pixel) -> PremultipliedPixel:
    """Premultiply assuming full coverage; only valid for already-opaque pixels."""

    if not pixel.is_opaque:
        raise ValueError("opaque_premultiplied requires a fully opaque pixel")
    return to_premultiplied(pixel)

