from __future__ import annotations

"""Low-level numeric helpers shared by the compositor.

These functions deal only in plain numbers: turning 8-bit channels into the
0..1 range the blend math wants, rounding back, and clamping. Keeping them in
one place means the conversion code and the over operator agree on how a float
becomes a byte (banker's rounding here is deliberately avoided so a half-step
always rounds up, matching the reference renderer the QA team compares against).
"""

CHANNEL_MAX = 255


def normalize(channel: int) -> float:
    """Map an 8-bit channel (0..255) into the unit interval."""

    return channel / CHANNEL_MAX


def denormalize(value: float) -> int:
    """Round a unit-interval value back to an 8-bit channel, clamped to 0..255."""

    scaled = value * CHANNEL_MAX
    rounded = int(scaled + 0.5) if scaled >= 0 else 0
    return clamp_channel(rounded)


def clamp_unit(value: float) -> float:
    """Clamp a float into [0.0, 1.0]."""

    if value < 0.0:
        return 0.0
    if value > 1.0:
        return 1.0
    return value


def clamp_channel(value: int) -> int:
    """Clamp an integer into the valid 8-bit channel range."""

    if value < 0:
        return 0
    if value > CHANNEL_MAX:
        return CHANNEL_MAX
    return value


def normalize_rgba(values: tuple[int, int, int, int]) -> tuple[float, float, float, float]:
    r, g, b, a = values
    return (normalize(r), normalize(g), normalize(b), normalize(a))


def denormalize_rgba(values: tuple[float, float, float, float]) -> tuple[int, int, int, int]:
    r, g, b, a = values
    return (denormalize(r), denormalize(g), denormalize(b), denormalize(a))


def lerp(start: float, end: float, t: float) -> float:
    """Linear interpolation, with ``t`` clamped to [0, 1]."""

    t = clamp_unit(t)
    return start + (end - start) * t


def approx_equal(left: float, right: float, tol: float = 1e-6) -> bool:
    return abs(left - right) <= tol


def coverage_complement(alpha: float) -> float:
    """The (1 - src_alpha) weight applied to the destination under 'over'."""

    return 1.0 - alpha


def weighted_sum(src_term: float, dst_term: float, dst_weight: float) -> float:
    """Combine a source term with a weighted destination term."""

    return src_term + dst_term * dst_weight


def channel_distance(left: tuple[int, ...], right: tuple[int, ...]) -> int:
    """Sum of absolute per-channel differences; handy for fringe diagnostics."""

    if len(left) != len(right):
        raise ValueError("tuples must be the same length")
    return sum(abs(a - b) for a, b in zip(left, right))


def brightness(rgb: tuple[int, int, int]) -> float:
    """A rough perceptual luminance used by tooling that flags dark halos."""

    r, g, b = rgb
    return 0.299 * r + 0.587 * g + 0.114 * b

