from __future__ import annotations

"""Flatten a stack of layers down to a single pixel.

A document is a stack of layers, each carrying one pixel here (a single sample
of the layer at one location) plus an opacity slider. The compositor walks the
stack from the bottom up, painting each visible layer over the running result
with the 'over' operator. Hidden layers are skipped; a layer's opacity scales
its source coverage before the blend.

``flatten`` returns the final straight-alpha pixel for the sampled location.
"""

from dataclasses import dataclass

from over_operator import composite_over, over_with_opacity
from pixel_models import Pixel


@dataclass(frozen=True)
class Layer:
    """One layer's sample at a location, plus its compositing controls."""

    name: str
    pixel: Pixel
    opacity: float = 1.0
    visible: bool = True

    def __post_init__(self) -> None:
        if not self.name.strip():
            raise ValueError("layer name is required")
        if self.opacity < 0.0 or self.opacity > 1.0:
            raise ValueError("opacity must be in 0.0..1.0")

    def effective_pixel(self) -> Pixel:
        """The source pixel after applying this layer's opacity to alpha."""

        if self.opacity >= 1.0:
            return self.pixel
        scaled = int(self.pixel.a * self.opacity + 0.5)
        return self.pixel.with_alpha(scaled)


def flatten(layers: list[Layer]) -> Pixel:
    """Composite a bottom-to-top stack into a single straight-alpha pixel.

    ``layers[0]`` is the bottom of the stack; later entries paint over it.
    Invisible layers are ignored. An empty (or fully hidden) stack flattens to
    transparent black.
    """

    visible = [layer for layer in layers if layer.visible]
    if not visible:
        return Pixel(0, 0, 0, 0)
    result = visible[0].effective_pixel()
    for layer in visible[1:]:
        result = over_with_opacity(layer.pixel, result, layer.opacity)
    return result


def flatten_pixels(pixels: list[Pixel]) -> Pixel:
    """Flatten a bottom-to-top list of plain pixels at full opacity."""

    if not pixels:
        return Pixel(0, 0, 0, 0)
    result = pixels[0]
    for pixel in pixels[1:]:
        result = composite_over(pixel, result)
    return result


def build_layer(
    name: str, pixel: Pixel, opacity: float = 1.0, visible: bool = True
) -> Layer:
    return Layer(name=name, pixel=pixel, opacity=opacity, visible=visible)


def visible_layer_count(layers: list[Layer]) -> int:
    return sum(1 for layer in layers if layer.visible)


def topmost_visible(layers: list[Layer]) -> Layer | None:
    """The layer that sits highest in a visible stack, if any."""

    for layer in reversed(layers):
        if layer.visible:
            return layer
    return None


def flatten_to_tuple(layers: list[Layer]) -> tuple[int, int, int, int]:
    return flatten(layers).as_tuple()


def composite_onto_background(layers: list[Layer], background: Pixel) -> Pixel:
    """Flatten the stack, then place the result over an opaque backdrop.

    Useful for export to a format with no alpha: the foreground is flattened
    first, then composited over the chosen background color.
    """

    foreground = flatten(layers)
    return composite_over(foreground, background)


def stack_summary(layers: list[Layer]) -> dict[str, object]:
    flat = flatten(layers)
    return {
        "layer_count": len(layers),
        "visible_count": visible_layer_count(layers),
        "result": flat.as_tuple(),
        "result_alpha": flat.a,
        "opaque": flat.is_opaque,
    }

