from __future__ import annotations

"""The Porter-Duff 'over' operator for straight-alpha pixels.

'src over dst' paints the source on top of the destination. The accumulated
alpha is ``out_a = src_a + dst_a * (1 - src_a)``. The color is the
alpha-weighted blend of the two contributions, normalized by the result alpha:

    out_rgb = (src_rgb * src_a + dst_rgb * dst_a * (1 - src_a)) / out_a

The clean way to compute that is to premultiply both inputs, add the weighted
premultiplied colors, then un-premultiply the sum by the result alpha. When the
result alpha is zero there is no color to recover, so the output is clear.
"""

from alpha_conversion import to_premultiplied, to_straight
from blend_math import coverage_complement
from pixel_models import Pixel, PremultipliedPixel


def composite_over(src: Pixel, dst: Pixel) -> Pixel:
    """Composite ``src`` over ``dst`` and return a straight-alpha pixel."""

    src_pre = to_premultiplied(src)
    dst_pre = to_premultiplied(dst)
    out_pre = over_premultiplied(src_pre, dst_pre)
    return to_straight(out_pre)


def over_premultiplied(
    src: PremultipliedPixel, dst: PremultipliedPixel
) -> PremultipliedPixel:
    """Combine two premultiplied pixels under 'over', staying premultiplied."""

    keep = coverage_complement(src.a)
    out_a = src.a + dst.a * keep
    if out_a <= 0.0:
        return PremultipliedPixel(0.0, 0.0, 0.0, 0.0)
    out_r = src.r + dst.r * keep
    out_g = src.g + dst.g * keep
    out_b = src.b + dst.b * keep
    return PremultipliedPixel(out_r, out_g, out_b, out_a)


def result_alpha(src: Pixel, dst: Pixel) -> int:
    """The 8-bit alpha that 'src over dst' produces, without the color blend."""

    return composite_over(src, dst).a


def is_fully_covered(src: Pixel, dst: Pixel) -> bool:
    """Whether the composite is fully opaque (so nothing shows through)."""

    return result_alpha(src, dst) == 255


def composite_over_tuple(
    src: tuple[int, int, int, int], dst: tuple[int, int, int, int]
) -> tuple[int, int, int, int]:
    """Convenience wrapper for callers holding raw RGBA byte tuples."""

    return composite_over(Pixel.from_tuple(src), Pixel.from_tuple(dst)).as_tuple()


def composite_chain(top_to_bottom: list[Pixel]) -> Pixel:
    """Composite a list of pixels where index 0 is the topmost source.

    Each pixel is painted over the accumulated result of everything below it.
    An empty chain is fully transparent.
    """

    if not top_to_bottom:
        return Pixel(0, 0, 0, 0)
    accumulated = top_to_bottom[-1]
    for pixel in reversed(top_to_bottom[:-1]):
        accumulated = composite_over(pixel, accumulated)
    return accumulated


def over_with_opacity(src: Pixel, dst: Pixel, opacity: float) -> Pixel:
    """Composite ``src`` over ``dst`` after scaling the source alpha by opacity.

    Layer opacity (0.0..1.0) multiplies into the source coverage before the
    blend, the same way a layer's opacity slider behaves.
    """

    if opacity < 0.0 or opacity > 1.0:
        raise ValueError("opacity must be in 0.0..1.0")
    scaled_alpha = int(src.a * opacity + 0.5)
    return composite_over(src.with_alpha(scaled_alpha), dst)


def blend_summary(src: Pixel, dst: Pixel) -> dict[str, object]:
    """A small diagnostic record used when QA inspects a single blend."""

    result = composite_over(src, dst)
    return {
        "src": src.as_tuple(),
        "dst": dst.as_tuple(),
        "result": result.as_tuple(),
        "result_alpha": result.a,
        "fully_covered": result.a == 255,
    }

