    Layer opacity (0.0..1.0) multiplies into the source coverage before the
    blend, the same way a layer's opacity slider behaves.
    """

    if opacity < 0.0 or opacity > 1.0:
        raise ValueError("opacity must be in 0.0..1.0")
    scaled_alpha = int(src.a * opacity + 0.5)
    return composite_over(src.with_alpha(scaled_alpha), dst)


def blend_summary(src: Pixel, dst: Pixel) -> dict[str, object]:
    """A small diagnostic record used when QA inspects a single blend."""

    result = composite_over(src, dst)
    return {
        "src": src.as_tuple(),
        "dst": dst.as_tuple(),
        "result": result.as_tuple(),
        "result_alpha": result.a,
        "fully_covered": result.a == 255,
    }

