from __future__ import annotations

"""Pixel value objects for the layer compositor.

The renderer keeps two flavours of the same color. A :class:`Pixel` holds
*straight* (non-premultiplied) RGBA: each channel is an 8-bit integer 0..255 and
the alpha is independent of the color channels. That is what designers paint and
what the file format stores. A :class:`PremultipliedPixel` holds the same color
with its RGB already scaled by alpha, kept as floats in 0..1 so the blend math
does not lose precision between steps.

Nothing here decides *how* to convert between the two forms; that lives next to
the blend math. These types only carry the numbers and guard their ranges.
"""

from dataclasses import dataclass


def _check_channel(name: str, value: int) -> int:
    if not isinstance(value, int):
        raise TypeError(f"{name} must be an int, got {type(value).__name__}")
    if value < 0 or value > 255:
        raise ValueError(f"{name} must be in 0..255, got {value}")
    return value


@dataclass(frozen=True)
class Pixel:
    """A straight-alpha RGBA pixel with 8-bit integer channels."""

    r: int
    g: int
    b: int
    a: int = 255

    def __post_init__(self) -> None:
        _check_channel("r", self.r)
        _check_channel("g", self.g)
        _check_channel("b", self.b)
        _check_channel("a", self.a)

    @property
    def is_opaque(self) -> bool:
        return self.a == 255

    @property
    def is_transparent(self) -> bool:
        return self.a == 0

    @property
    def rgb(self) -> tuple[int, int, int]:
        return (self.r, self.g, self.b)

    def as_tuple(self) -> tuple[int, int, int, int]:
        return (self.r, self.g, self.b, self.a)

    def with_alpha(self, a: int) -> "Pixel":
        return Pixel(self.r, self.g, self.b, a)

    @classmethod
    def from_tuple(cls, values: tuple[int, int, int, int]) -> "Pixel":
        r, g, b, a = values
        return cls(int(r), int(g), int(b), int(a))

    @classmethod
    def opaque(cls, r: int, g: int, b: int) -> "Pixel":
        return cls(r, g, b, 255)

    @classmethod
    def clear(cls) -> "Pixel":
        return cls(0, 0, 0, 0)


@dataclass(frozen=True)
class PremultipliedPixel:
    """A premultiplied-alpha pixel kept as normalized floats in 0..1.

    ``r``/``g``/``b`` are already scaled by ``a`` (so for a valid pixel each is
    <= ``a``). Working in floats keeps intermediate blends from quantizing on
    every step; the result is rounded back to 8-bit only at the edges.
    """

    r: float
    g: float
    b: float
    a: float

    def __post_init__(self) -> None:
        for name in ("r", "g", "b", "a"):
            value = getattr(self, name)
            if value < -1e-6 or value > 1.0 + 1e-6:
                raise ValueError(f"{name} must be in 0.0..1.0, got {value}")

    @property
    def is_transparent(self) -> bool:
        return self.a <= 0.0

    def as_tuple(self) -> tuple[float, float, float, float]:
        return (self.r, self.g, self.b, self.a)

    def scale_rgb(self, factor: float) -> "PremultipliedPixel":
        return PremultipliedPixel(self.r * factor, self.g * factor, self.b * factor, self.a)


def make_pixel(r: int, g: int, b: int, a: int = 255) -> Pixel:
    """Convenience builder mirroring how callers construct test fixtures."""

    return Pixel(r, g, b, a)


def gray(level: int, a: int = 255) -> Pixel:
    """A neutral gray at the given level, optionally semi-transparent."""

    return Pixel(level, level, level, a)


def pixels_equal(left: Pixel, right: Pixel) -> bool:
    return left.as_tuple() == right.as_tuple()

